import json
import numpy as np
q, beta = 4, 8.0
def code(x):
    return np.array([1.0 if (x >> k) & 1 else -1.0 for k in range(q)])
Ad = np.zeros((4, q)); It = np.zeros((4, q)); occ = np.zeros(4)
for a, b in [(3, 9), (6, 5)]:
    i = int(np.argmin(occ)); Ad[i] = code(a); It[i] = code(b); occ[i] = 1.0
def get(a):
    s = np.where(occ > 0.5, Ad @ code(a), -1e9)
    if s.max() < q - 0.5:
        return -1
    w = np.exp(beta * (s - s.max())); w = w / w.sum()
    r = w @ It
    return int(sum(2 ** k for k in range(q) if r[k] > 0))
print(json.dumps({"get3": get(3), "get6": get(6), "get1": get(1)}))
